class PlanFeasibilityTest {
 private val vector="""{"action":"assign-program-plan","workspaceId":"w","idempotencyKey":"or1-b91f0176ec74475e8cf7406e25b7e9d3-assignment-vector","assignmentPlan":{"assignmentId":"00000000-0000-4000-8000-000000000003","clientUid":"B","templateId":"00000000-0000-4000-8000-000000000001","versionId":"v0000000001","versionNumber":1,"sourceContentHash":"b32edc3d3e84a4056d05d091c958b5a70705a5f5fad8981a9f0e575758ad557b","copyPolicyVersion":1,"snapshotHash":"8da61bd9833c4a36604381ebafc92f7cb17cc2427267110db43dbb9b76fceb87","authority":{"trainerLifecycleRevision":1,"trainerMembershipRevision":1,"clientLifecycleRevision":1,"clientMembershipRevision":1,"workspaceMembershipRevision":1,"clientOnboardingRevision":1},"preparedAtMillis":1800000000000,"accessExpiresAtMillis":1800086403000,"schedulePolicyVersion":2,"expectedHorizonRevision":0,"horizonRevision":1,"planHash":"22e034c871bf85ec157c149e72fc4d7a6afe1720443d5feec4de69bab9c6d60a","occurrences":[{"plannedWorkoutId":"00000000-0000-4000-8000-000000000200","workoutId":"00000000-0000-4000-8000-000000000100","scheduledInstantMillis":1800000001000},{"plannedWorkoutId":"00000000-0000-4000-8000-000000000201","workoutId":"00000000-0000-4000-8000-000000000101","scheduledInstantMillis":1800000002000},{"plannedWorkoutId":"00000000-0000-4000-8000-000000000202","workoutId":"00000000-0000-4000-8000-000000000102","scheduledInstantMillis":1800000003000}]}}"""
 @Test fun exactVectorAndUnsupportedProductReader() {
  val d=PlanFeasibility.parse("A",vector)
  assertEquals("10ecf1aaf8995c961a9fc23628d051cfde08cf3beb124d55c005433ded765a8e",PlanFeasibility.hash("A",d))
  assertEquals("22e034c871bf85ec157c149e72fc4d7a6afe1720443d5feec4de69bab9c6d60a",d.assignmentPlan.planHash)
  assertFails{AssignmentContract.parseDescriptor("A",vector)}
  for(policy in listOf(0,1,3))assertFalse(PlanFeasibility.valid("A",d.copy(assignmentPlan=d.assignmentPlan.copy(schedulePolicyVersion=policy))))
  assertFalse(PlanFeasibility.valid("B",d))
  val base=AccountPersistenceEnvelope(uid="A")
  assertTrue(PlanFeasibility.admission(base,d));assertEquals(38,PlanFeasibility.states(base,d).size)
  assertFails{PersistenceJson.format.decodeFromString(AccountPersistenceEnvelope.serializer(),PlanFeasibility.states(base,d).first().toString())}
  assertFalse(PlanFeasibility.admission(base.copy(preferredWorkspaceId="x".repeat(36500)),d))
 }
 @Test fun exactTimeOrderAndImmutableDigest() {
  val d=PlanFeasibility.parse("A",vector);val a=d.assignmentPlan
  for(o in listOf(a.occurrences.reversed(),a.occurrences+a.occurrences.first(),a.occurrences.drop(1)))assertFalse(PlanFeasibility.valid("A",d.copy(assignmentPlan=a.copy(occurrences=o))))
  assertFalse(PlanFeasibility.valid("A",d.copy(assignmentPlan=a.copy(accessExpiresAtMillis=a.accessExpiresAtMillis+1))))
  assertFalse(PlanFeasibility.valid("A",d.copy(assignmentPlan=a.copy(preparedAtMillis=Long.MAX_VALUE))))
 }
